import { Show, type ParentComponent } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

import { type CityBannerIdentity } from "./city-banner-data.js";

export interface CityBannerNameTooltipProps {
	data: Pick<CityBannerIdentity, "leaderName" | "civName" | "cityStateBonusName">;
}

/**
 * The `city-banner__tooltip` name tooltip, showing the leader/suzerain name, civilization name, and
 * (for city-states/villages) the city-state bonus name. Ported from the raw HTML string built by the
 * legacy `city-banners.ts` `queueNameUpdate()`; each line is resolved and composed here instead of by
 * `city-banner-data.ts`, so the data layer only ever exposes raw (unstylized) localization keys.
 */
export const CityBannerNameTooltip: ParentComponent<CityBannerNameTooltipProps> = (props) => {
	return (
		<Tooltip showFiligrees={false}>
			<Tooltip.Trigger>{props.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame class="relative flex flex-col pb-1 max-w-128">
					<div class="flex-auto p-0">
						<Show when={props.data.leaderName}>
							<div>
								<L10n.Compose text={props.data.leaderName} />
							</div>
						</Show>
						<div>
							<L10n.Compose text={props.data.civName} />
						</div>
						<Show when={props.data.cityStateBonusName}>
							<div>
								<L10n.Compose text={props.data.cityStateBonusName} />
							</div>
						</Show>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};
